        alias_generator=to_camel, validate_by_name=True, validate_by_alias=True
    )
    input_metadata: InputMetadata
    engagement_id: str


AgentRoomMetadata = Union[LocalDevAgentRoomMetadata, ScreeningAgentRoomMetadata]


def parse_input_metadata(metadata_json: str) -> InputMetadata:
    """Parse input metadata from JSON string"""
    try:
        data = json.loads(metadata_json)
        kind = data.get("kind", CallKind.WEB)

        if kind == CallKind.INBOUND:
            return InboundInputMetadata(**data)
        elif kind == CallKind.OUTBOUND:
            return OutboundInputMetadata(**data)
        elif kind == CallKind.PLAYGROUND:
            return PlaygroundInputMetadata(**data)
        else:
            return WebInputMetadata(**data)
    except (json.JSONDecodeError, ValueError):
        logger.warning(
            "Unable to parse input metadata. returning default", raw_data=metadata_json
        )
        return PlaygroundInputMetadata(
            agent=AgentType.SCREENING,
            engagement_id=None,
            opportunity_id="",
        )


def create_input_metadata(
    kind: CallKind,
    base_data: Dict[str, Any],
    additional_data: Optional[Dict[str, Any]] = None,
) -> InputMetadata:
    """Factory function to create appropriate input metadata"""
    data = base_data.copy()
    if additional_data:
        data.update(additional_data)

    if kind == CallKind.INBOUND:
        return InboundInputMetadata(**data)
    elif kind == CallKind.OUTBOUND:
        return OutboundInputMetadata(**data)
    elif kind == CallKind.PLAYGROUND:
        return PlaygroundInputMetadata(**data)
    else:
        return WebInputMetadata(**data)

